def _cmd_record(
    config_path,
    events_path,
    log_path,
    max_events,
    max_log_bytes,
    max_config_bytes,
    max_events_bytes,
    max_output_bytes,
    max_record_work,
):
    try:
        with open(config_path, "rb") as config_handle, open(
            events_path, "rb"
        ) as events_handle:
            # 两文件均可读后，先判 CONFIG 原始字节，再判 EVENTS 原始字节
            config_raw = _read_limited(config_handle, max_config_bytes)
            if config_raw is None:
                _fail("config_limit")
                return 5
            events_raw = _read_limited(events_handle, max_events_bytes)
            if events_raw is None:
                _fail("events_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        # 事件上界先于解析与预演判定；超限时绝不触碰 LOG
        events_preview = parse_json(events_raw)
        if isinstance(events_preview, list) and len(events_preview) > max_events:
            _fail("event_limit")
            return 5
        # 先无副作用预演：解析、全部校验与各重载点检测均在内存完成；
        # 工作量预演在语义校验后、正式仿真与 LOG 构造前，超限绝不触碰 LOG
        config = parse_json(config_raw)
        events = events_preview
        mode = _log_mode(config)
        if mode == "fdb":
            result, observer = _run_fdb(
                config, events, True, max_record_work
            )
        elif mode == "stp":
            result, observer = _run_stp(
                config, events, True, max_record_work
            )
        elif mode == "loop":
            result, observer = _run_loop_detect(
                config, events, True, max_record_work
            )
        elif mode == "link_forward":
            result, observer = _run_link_forward(
                config, events, True, max_record_work
            )
        elif mode == "forward":
            result, observer = _run_forward(
                config, events, True, max_record_work
            )
        elif mode == "link_state":
            result, observer = _run_link_state(
                config, events, True, max_record_work
            )
        elif mode == "forward_static":
            result, observer = _run_forward_static(
                config, events, True, max_record_work
            )
        elif mode == "forward_stp":
            result, observer = _run_forward_stp(
                config, events, True, max_record_work
            )
        elif mode == "forward_decode":
            result, observer = _run_forward_decode(
                config, events, True, max_record_work
            )
        elif mode == "stp_decode":
            result, observer = _run_stp_decode(
                config, events, True, max_record_work
            )
        elif mode == "forward_stp_storm":
            result, observer = _run_forward_stp_storm(
                config, events, True, max_record_work
            )
        elif mode == "lag":
            result, observer = _run_lag(
                config, events, True, max_record_work
            )
        elif mode == "mirror":
            result, observer = _run_mirror(
                config, events, True, max_record_work
            )
        elif mode == "acl":
            result, observer = _run_acl(
                config, events, True, max_record_work
            )
        elif mode == "security_check":
            result, observer = _run_security_check(
                config, events, True, max_record_work
            )
        elif mode == "acl_check":
            result, observer = _run_acl_check(
                config, events, True, max_record_work
            )
        elif mode == "qos":
            result, observer = _run_qos(
                config, events, True, max_record_work
            )
        elif mode == "qos_check":
            result, observer = _run_qos_check(
                config, events, True, max_record_work
            )
        elif mode == "mirror_check":
            result, observer = _run_mirror_check(
                config, events, True, max_record_work
            )
        elif mode == "lag_check":
            result, observer = _run_lag_check(
                config, events, True, max_record_work
            )
        elif mode == "storm_check":
            result, observer = _run_storm_check(
                config, events, True, max_record_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_record_work
            )
        doc = _build_log_doc(config, events, observer["items"])
        payload = _log_bytes(doc)
        # 字节上界（含末尾 LF）在写入前判定；等于上限合法
        if len(payload) > max_log_bytes:
            _fail("log_limit")
            return 5
        # 输出上界在 log_limit 之后、原子写 LOG 之前判定；超限时绝不触碰 LOG
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
        _atomic_write(log_path, payload)  # 成功后才原子写 LOG
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (
        ReloadWorkLimit,
        StpWorkLimit,
        LoopWorkLimit,
        FdbWorkLimit,
        ForwardWorkLimit,
        ForwardStpWorkLimit,
        LinkForwardWorkLimit,
        LinkWorkLimit,
        SecurityWorkLimit,
        QosWorkLimit,
        AclWorkLimit,
        MirrorWorkLimit,
        LagWorkLimit,
        StormWorkLimit,
    ):
        _fail("record_work_limit")
        return 5
    except OSError:
        _fail("file_not_found")
        return 3
    sys.stdout.buffer.write(output)
    return 0


def _cmd_replay(
    log_path,
    max_events,
    max_log_bytes,
    max_output_bytes,
    max_replay_work,
    expected_sha256=None,
):
    try:
        with open(log_path, "rb") as handle:
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    # 字节上界先判定（分块读取、超限即停，含末尾 LF）
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        log = parse_json(log_raw)  # 全量校验先于重放
        _validate_log_shape(log)
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != log["sha256"]:
            raise InvalidInput("bad log sha256")
        # 外部承诺先于事件数与一切语义重放：EXPECTED 须是调用方从成功
        # record 产物顶层 sha256 独立保存的值，绝不取自待重放 LOG。仅改
        # 帧并重算 LOG 内摘要的等价重写虽能通过内部自洽校验，仍因外部
        # 承诺不符在此失败（stdout 空、LOG 不动）
        if expected_sha256 is not None and expected_sha256 != log["sha256"]:
            raise InvalidInput("bad log sha256")
        config = log["config"]
        events = [record["event"] for record in log["records"]]
        # records 上界在解析校验后、重放前判定
        if len(log["records"]) > max_events:
            _fail("event_limit")
            return 5
        # 状态语义校验后先按 record 同一公式无副作用预演；首次超限即停止，
        # 不正式重放，LOG 保持不动
        mode = _log_mode(config)
        if mode == "fdb":
            result, observer = _run_fdb(
                config, events, True, max_replay_work
            )
        elif mode == "stp":
            result, observer = _run_stp(
                config, events, True, max_replay_work
            )
        elif mode == "loop":
            result, observer = _run_loop_detect(
                config, events, True, max_replay_work
            )
        elif mode == "link_forward":
            result, observer = _run_link_forward(
                config, events, True, max_replay_work
            )
        elif mode == "forward":
            result, observer = _run_forward(
                config, events, True, max_replay_work
            )
        elif mode == "link_state":
            result, observer = _run_link_state(
                config, events, True, max_replay_work
            )
        elif mode == "forward_static":
            result, observer = _run_forward_static(
                config, events, True, max_replay_work
            )
        elif mode == "forward_stp":
            result, observer = _run_forward_stp(
                config, events, True, max_replay_work
            )
        elif mode == "forward_decode":
            result, observer = _run_forward_decode(
                config, events, True, max_replay_work
            )
        elif mode == "stp_decode":
            result, observer = _run_stp_decode(
                config, events, True, max_replay_work
            )
        elif mode == "forward_stp_storm":
            result, observer = _run_forward_stp_storm(
                config, events, True, max_replay_work
            )
        elif mode == "lag":
            result, observer = _run_lag(
                config, events, True, max_replay_work
            )
        elif mode == "mirror":
            result, observer = _run_mirror(
                config, events, True, max_replay_work
            )
        elif mode == "acl":
            result, observer = _run_acl(
                config, events, True, max_replay_work
            )
        elif mode == "security_check":
            result, observer = _run_security_check(
                config, events, True, max_replay_work
            )
        elif mode == "acl_check":
            result, observer = _run_acl_check(
                config, events, True, max_replay_work
            )
        elif mode == "qos":
            result, observer = _run_qos(
                config, events, True, max_replay_work
            )
        elif mode == "qos_check":
            result, observer = _run_qos_check(
                config, events, True, max_replay_work
            )
        elif mode == "mirror_check":
            result, observer = _run_mirror_check(
                config, events, True, max_replay_work
            )
        elif mode == "lag_check":
            result, observer = _run_lag_check(
                config, events, True, max_replay_work
            )
        elif mode == "storm_check":
            result, observer = _run_storm_check(
                config, events, True, max_replay_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_replay_work
            )
        _verify_records(log, events, observer["items"])
        # 重放重建的 LOG 须与原文件逐字节一致（含 sha256 与 LF）
        rebuilt = _build_log_doc(config, events, observer["items"])
        if _log_bytes(rebuilt) != log_raw:
            raise InvalidInput("bad log")
        # 输出上界在全部日志语义与重放核对成功后判定；LOG 保持不动
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (
        ReloadWorkLimit,
        StpWorkLimit,
        LoopWorkLimit,
        FdbWorkLimit,
        ForwardWorkLimit,
        ForwardStpWorkLimit,
        LinkForwardWorkLimit,
        LinkWorkLimit,
        SecurityWorkLimit,
        QosWorkLimit,
        AclWorkLimit,
        MirrorWorkLimit,
        LagWorkLimit,
        StormWorkLimit,
    ):
        _fail("replay_work_limit")
        return 5
    sys.stdout.buffer.write(output)
    return 0


CONFIG_DIFF_MAX_INPUT_BYTES = 1024 * 1024


def _json_pointer_token(token):
    """RFC6901 reference token 转义：~ 编码为 ~0，/ 编码为 ~1。"""
    return token.replace("~", "~0").replace("/", "~1")


def _diff_collect(old, new, path, changes):
    """按键序无关契约收集 OLD、NEW 的差异项到 changes。

    对象递归，键按 Unicode 码点升序深度优先；数组整体比较且顺序敏感，
    整组不同仅出一项；标量按 JSON 类型与值比较。path 为 RFC6901 JSON
    Pointer（根为 ""）。仅不同的数组或标量（及缺失对象键）生成项。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        for key in sorted(set(old) | set(new)):
            child = path + "/" + _json_pointer_token(key)
            if key in old and key in new:
                _diff_collect(old[key], new[key], child, changes)
            elif key in old:
                # 仅旧侧存在；合法 port-security 配置各层键集固定，不会到达
                changes.append(
                    {"path": child, "before": _canonical(old[key]),
                     "after": None}
                )
            else:
                changes.append(
                    {"path": child, "before": None,
                     "after": _canonical(new[key])}
                )
        return
    # 两数组整体（顺序敏感）、两标量（JSON 类型+值）或类别不一致：
    # 不同即整值一项，前后值按同一规则规范化
    if not _json_equal(old, new):
        changes.append(
            {"path": path, "before": _canonical(old),
             "after": _canonical(new)}
        )


def _diff_size(value):
    """工作量公式的 S：标量 1；数组 1+各元素 S 之和；
    对象 1+键数+各值 S 之和。"""
    if isinstance(value, dict):
        return 1 + len(value) + sum(_diff_size(item) for item in value.values())
    if isinstance(value, list):
        return 1 + sum(_diff_size(item) for item in value)
    return 1


def _diff_size_charge(value, remaining):
    """S 的计费版：从剩余额度扣减 S(value)，返回扣后额度（耗尽为 0）。

    对象先计 1+键数，再按键的 Unicode 码点升序逐值计费；数组先计 1，
    再按元素序逐项计费；标量计 1。累计首次超过剩余额度即抛
    DiffWorkLimit，不再访问后续元素或键值；额度足够时累计恰为
    S(value)，与 _diff_size 一致。
    """
    if isinstance(value, dict):
        cost = 1 + len(value)
        if cost > remaining:
            raise DiffWorkLimit
        remaining -= cost
        for key in sorted(value):
            remaining = _diff_size_charge(value[key], remaining)
        return remaining
    if isinstance(value, list):
        if remaining < 1:
            raise DiffWorkLimit
        remaining -= 1
        for item in value:
            remaining = _diff_size_charge(item, remaining)
        return remaining
    if remaining < 1:
        raise DiffWorkLimit
    return remaining - 1


def _diff_work(old, new, remaining):
    """按工作量公式无副作用预演 D，返回剩余额度（耗尽为 0）。

    两值均为对象时计 1+并集键数，共有键递归计 D，单侧键计该侧 S；
    其余（含数组整体）计 1+S(旧值)+S(新值)。键按 Unicode 码点升序
    累计，递归逐层传递剩余额度；等于上限合法，首次超过即抛
    DiffWorkLimit，此后不再访问后续元素、键值或单侧子树。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        cost = 1 + len(set(old) | set(new))
        if cost > remaining:
            raise DiffWorkLimit
        remaining -= cost
        for key in sorted(set(old) | set(new)):
            if key in old and key in new:
                remaining = _diff_work(old[key], new[key], remaining)
            else:
                remaining = _diff_size_charge(
                    old[key] if key in old else new[key], remaining
                )
        return remaining
    if remaining < 1:
        raise DiffWorkLimit
    remaining -= 1
    remaining = _diff_size_charge(old, remaining)
    return _diff_size_charge(new, remaining)


def _cmd_config_diff(
    old_path,
    new_path,
    max_diff_work=DEFAULT_MAX_DIFF_WORK,
    max_input_bytes=CONFIG_DIFF_MAX_INPUT_BYTES,
    max_output_bytes=None,
):
    if max_output_bytes is None:
        # 调用时解析缺省：测试可在导入后补丁 DEFAULT_MAX_OUTPUT_BYTES
        max_output_bytes = DEFAULT_MAX_OUTPUT_BYTES
    try:
        # 先打开两文件，任一失败即停；均可读后按 OLD、NEW 顺序分块读
        with open(old_path, "rb") as old_handle, open(
            new_path, "rb"
        ) as new_handle:
            old_raw = _read_limited(old_handle, max_input_bytes)

def validate_stp_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != STP_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # bridges/links/delay/bridge/ports/age 与 forward-stp 契约一致，复用其全量校验
    bridges, links, delay, bridge, ports, age = validate_forward_stp_config(
        {key: config[key] for key in FORWARD_STP_CONFIG_KEYS}
    )
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    return bridges, links, delay, bridge, ports, age, max_frame


def validate_stp_check_events(events, ports, link_ids):
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    names = {port["name"] for port in ports}
    result = []
    prev_t = None
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == STP_EVENT_KEYS:
            t = event["t"]
            lid = event["id"]
            up = event["up"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(lid, str) or not lid or lid not in link_ids:
                raise InvalidInput("bad event id")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("link", t, lid, up))
        elif keys == STP_CHECK_FRAME_KEYS:
            t = event["t"]
            port = event["port"]
            src = event["src"]
            dst = event["dst"]
            vlan = event["vlan"]
            length = event["length"]
            fcs = event["fcs"]
            alignment = event["alignment"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            if not valid_mac(src):
                raise InvalidInput("bad src")
            if not valid_dst_mac(dst):
                raise InvalidInput("bad dst")
            if vlan is not None and not _valid_vlan_id(vlan):
                raise InvalidInput("bad vlan")
            if not _is_int(length) or length < 0:
                raise InvalidInput("bad length")
            if not isinstance(fcs, bool):
                raise InvalidInput("bad fcs")
            if not isinstance(alignment, bool):
                raise InvalidInput("bad alignment")
            result.append(
                ("frame", t, port, src, dst, vlan, length, fcs, alignment)
            )
        else:
            raise InvalidInput("bad event")
        prev_t = t
    return result


def forward_stp_check(
    bridges, links, delay, bridge_name, ports, age, max_frame, events,
    observer=None,
):
    """observer 非 None 时（record/replay）逐事件记录 applied 与输出：

    链路项仅 up 实际改变时 applied，output 恒 None；帧项恒 applied，
    output 为对应 results 项（键序 t,class,action,ports）。
    """
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    port_link = {}  # 本桥桥链路口名 -> link
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [port, seen]
    port_stats = {
        port["name"]: {
            "rx": 0,
            "tx": 0,
            "drop": 0,
            "good": 0,
            "runt": 0,
            "giant": 0,
            "alignment": 0,
            "bad_fcs": 0,
        }
        for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    results = []
    if observer is not None:  # record/replay：逐事件记录 applied 与输出
        observer["items"] = []

    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        """返回 (物理 up, STP 状态)；边缘口恒为 up 即 forwarding。"""
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"  # alternate
        return True, state

    converge(0)
    for item in events:
        t = item[1]
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        if item[0] == "link":
            _, t, lid, up = item
            applied = by_id[lid]["up"] != up  # up 实际改变才 applied
            old_forwarding = forwarding_ports(t)
            by_id[lid]["up"] = up
            converge(t)
            for name in old_forwarding - forwarding_ports(t):
                for key in [k for k, (p, _) in fdb.items() if p == name]:
                    del fdb[key]
            if observer is not None:  # 链路项：output 恒 None
                observer["items"].append(
                    {"kind": "link", "t": t, "applied": applied,
                     "output": None}
                )
            continue
        _, t, port_name, src, dst, tag, length, fcs, alignment = item
        port_stats[port_name]["rx"] += 1
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        port_stats[port_name][cls] += 1
        if cls != "good":  # 非 good 丢弃且不学习、不转发、不计 VLAN
            port_stats[port_name]["drop"] += 1
            entry = {"t": t, "class": cls, "action": "drop", "ports": []}
            results.append(entry)
            if observer is not None:  # 帧项恒 applied，output 为对应结果
                observer["items"].append(
